# t(key): no hardcoded strings; fallback chain es-MX -> es -> en
locales = {
    'en': {'hello': 'Hello, {name}!', 'save': 'Save'},
    'es': {'hello': '¡Hola, {name}!'},  # 'save' missing -> fallback
}

def t(key, lang, **vars):
    chain = [lang] + ([lang.split('-')[0]] if '-' in lang else []) + ['en']
    for l in chain:
        if key in locales.get(l, {}):
            return locales[l][key].format(**vars)
    return key

print(t('hello', 'es-MX', name='Jo'))
print(t('save', 'es-MX'), '(fallback to en: never a missing key)')
print('lint bans hardcoded UI strings: a literal is a bug')

# ICU plural: the LOGIC travels with the message (translators reorder freely)
def icu_plural(n, one, other):
    # real: CLDR rules per locale (Arabic has 6 forms!)
    return one.replace('#', str(n)) if n == 1 else other.replace('#', str(n))

for n in (1, 5):
    print('en:', icu_plural(n, '# file', '# files'))
# Russian: 1 файл, 2-4 файла, 5+ файлов (3 forms!)
def ru_plural(n):
    if n % 10 == 1 and n % 100 != 11:
        return '%d файл' % n
    if n % 10 in (2, 3, 4) and n % 100 not in (12, 13, 14):
        return '%d файла' % n
    return '%d файлов' % n
print('ru:', [ru_plural(n) for n in (1, 3, 5)])
print('never "if n==1" in code: CLDR rules per locale')

# best match: user's priority list vs supported (NOT geo-IP)
supported = ['en', 'es', 'fr']
user_prefs = ['es-MX', 'es', 'en-US']  # Accept-Language, priority order

def best_match(prefs, supported):
    for p in prefs:
        if p in supported:
            return p
        base = p.split('-')[0]
        if base in supported:
            return base
    return 'en'

print('user', user_prefs, '->', best_match(user_prefs, supported))
print('override always available (?lang=es); persists; never geo-IP for language')

# pseudo-locale: lengthen + accent + bracket (exposes i18n bugs pre-translation)
def pseudo(s):
    accented = s.translate(str.maketrans('aeiou', 'àęįøü'))
    return '[!! %s %s !!]' % (accented, '~' * (len(s) // 3))

for s in ('Save', 'Delete selected items'):
    print('%-22r -> %r' % (s, pseudo(s)))
print('exposes: hardcoded strings (untransformed), layout breaks, encoding bugs')
print('run the FULL suite in pseudo-locale: CI, always')

# fallback chain: es-MX -> es -> en -> key (never blank, misses logged)
locales = {'en': {'save': 'Save', 'new': 'New'}, 'es': {'save': 'Guardar'}}
misses = []

def t(key, lang):
    for l in (lang, lang.split('-')[0], 'en'):
        if key in locales.get(l, {}):
            return locales[l][key]
    misses.append((lang, key))
    return key  # last resort: the key itself (never blank)

print(t('save', 'es-MX'), '|', t('new', 'es-MX'), '(fell back to en)')
print(t('nope', 'es-MX'), '(key itself; logged:)')
print('untranslated keys:', misses, '-> dashboard for translators')

# term base: deviations flagged in the TMS
terms = {'dashboard': {'es': 'panel', 'never': ['tablero', 'salpicadero']}}

def check(term, lang, translation):
    entry = terms[term][lang]
    banned = terms[term]['never']
    if translation == entry:
        return 'OK'
    if translation in banned:
        return 'FLAGGED: inconsistent term'
    return 'REVIEW'

print('dashboard -> "panel":', check('dashboard', 'es', 'panel'))
print('dashboard -> "tablero":', check('dashboard', 'es', 'tablero'))
print('tone: formal/informal "you" per locale style guide; brand terms never translate')
